// === MIND-BLOWING GALAXY COLLISION SIMULATION ===
// 4000 particles, two supermassive cores, gravitational tides in real-time

let scene, camera, renderer;
let points, geometry, material;
let fadeScene, fadeCamera, fadeMesh;

const NUM_PARTICLES = 4000;
const G = 1.2;
const DT = 0.08;
const SOFTENING = 1.5;
const TRAIL_OPACITY = 0.04;

// Camera orbit state
let camRadius = 140;
let camTheta = 0.2;
let camPhi = 1.2;
let isDragging = false;
let lastMX = 0, lastMY = 0;

// Two galactic centers
const center1 = {
    pos: new THREE.Vector3(-45, 0, 0),
    vel: new THREE.Vector3(0.15, 0.32, 0),
    mass: 4000,
    mesh: null
};
const center2 = {
    pos: new THREE.Vector3(45, 0, 0),
    vel: new THREE.Vector3(-0.15, -0.32, 0.08),
    mass: 4000,
    mesh: null
};

let velocities = [];
let initialColors = []; // store galaxy identity

function updateCamera() {
    camera.position.x = camRadius * Math.sin(camPhi) * Math.cos(camTheta);
    camera.position.y = camRadius * Math.cos(camPhi);
    camera.position.z = camRadius * Math.sin(camPhi) * Math.sin(camTheta);
    camera.lookAt(0, 0, 0);
}

function init() {
    // Scene
    scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x020105, 0.0015);

    // Camera
    camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 1000);
    updateCamera();

    // Renderer with trail support
    renderer = new THREE.WebGLRenderer({ antialias: false, preserveDrawingBuffer: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.autoClear = false;
    renderer.domElement.style.cursor = 'move';
    document.body.appendChild(renderer.domElement);

    // === FADE OVERLAY FOR TRAILS ===
    fadeScene = new THREE.Scene();
    fadeCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const fadeGeo = new THREE.PlaneGeometry(2, 2);
    const fadeMat = new THREE.MeshBasicMaterial({
        color: 0x020105,
        transparent: true,
        opacity: TRAIL_OPACITY,
        depthTest: false,
        depthWrite: false
    });
    fadeMesh = new THREE.Mesh(fadeGeo, fadeMat);
    fadeMesh.position.z = -0.5;
    fadeScene.add(fadeMesh);

    // === BACKGROUND STARS ===
    const bgGeo = new THREE.BufferGeometry();
    const bgPos = new Float32Array(2000 * 3);
    const bgColors = new Float32Array(2000 * 3);
    for (let i = 0; i < 2000; i++) {
        const r = 300 + Math.random() * 400;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);
        bgPos[i*3] = r * Math.sin(phi) * Math.cos(theta);
        bgPos[i*3+1] = r * Math.sin(phi) * Math.sin(theta);
        bgPos[i*3+2] = r * Math.cos(phi);
        const brightness = 0.3 + Math.random() * 0.7;
        bgColors[i*3] = brightness;
        bgColors[i*3+1] = brightness * (0.8 + Math.random() * 0.2);
        bgColors[i*3+2] = brightness * (0.9 + Math.random() * 0.1);
    }
    bgGeo.setAttribute('position', new THREE.BufferAttribute(bgPos, 3));
    bgGeo.setAttribute('color', new THREE.BufferAttribute(bgColors, 3));
    const bgMat = new THREE.PointsMaterial({
        size: 1.2,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        transparent: true,
        opacity: 0.6
    });
    scene.add(new THREE.Points(bgGeo, bgMat));

    // === GALACTIC CENTER GLOW ===
    const glowGeo = new THREE.SphereGeometry(3, 32, 32);
    const glowMat = new THREE.MeshBasicMaterial({ color: 0xfff8e7, blending: THREE.AdditiveBlending, transparent: true, opacity: 0.9 });
    center1.mesh = new THREE.Mesh(glowGeo, glowMat);
    center2.mesh = new THREE.Mesh(glowGeo.clone(), glowMat.clone());
    scene.add(center1.mesh);
    scene.add(center2.mesh);

    // === PARTICLE SYSTEM ===
    geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(NUM_PARTICLES * 3);
    const colors = new Float32Array(NUM_PARTICLES * 3);

    // Galaxy 1: face-on disk in XY plane
    for (let i = 0; i < NUM_PARTICLES / 2; i++) {
        const angle = Math.random() * Math.PI * 2;
        // Exponential disk profile
        const r = 2 + 30 * Math.pow(Math.random(), 0.6);
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        const z = (Math.random() - 0.5) * (1.5 + r * 0.05);

        // Keplerian orbital velocity around center1
        const vMag = Math.sqrt(G * center1.mass / Math.sqrt(r*r + 4)) * (0.85 + Math.random() * 0.3);
        const vx = -vMag * Math.sin(angle);
        const vy = vMag * Math.cos(angle);
        const vz = (Math.random() - 0.5) * 0.1;

        positions[i*3] = center1.pos.x + x;
        positions[i*3+1] = center1.pos.y + y;
        positions[i*3+2] = center1.pos.z + z;

        velocities.push(new THREE.Vector3(vx + center1.vel.x, vy + center1.vel.y, vz + center1.vel.z));

        // Cool blue-white identity
        initialColors.push(0);
        colors[i*3] = 0.4 + Math.random() * 0.4;
        colors[i*3+1] = 0.6 + Math.random() * 0.4;
        colors[i*3+2] = 1.0;
    }

    // Galaxy 2: tilted disk (rotated 60° around X)
    const tilt = Math.PI / 3;
    const cosT = Math.cos(tilt);
    const sinT = Math.sin(tilt);

    for (let i = NUM_PARTICLES / 2; i < NUM_PARTICLES; i++) {
        const angle = Math.random() * Math.PI * 2;
        const r = 2 + 30 * Math.pow(Math.random(), 0.6);
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        const z = (Math.random() - 0.5) * (1.5 + r * 0.05);

        // Apply tilt rotation
        const rx = x;
        const ry = y * cosT - z * sinT;
        const rz = y * sinT + z * cosT;

        const vMag = Math.sqrt(G * center2.mass / Math.sqrt(r*r + 4)) * (0.85 + Math.random() * 0.3);
        const vx = -vMag * Math.sin(angle);
        const vy = vMag * Math.cos(angle);
        const vz = (Math.random() - 0.5) * 0.1;

        // Rotate velocity by same tilt
        const rvx = vx;
        const rvy = vy * cosT - vz * sinT;
        const rvz = vy * sinT + vz * cosT;

        positions[i*3] = center2.pos.x + rx;
        positions[i*3+1] = center2.pos.y + ry;
        positions[i*3+2] = center2.pos.z + rz;

        velocities.push(new THREE.Vector3(rvx + center2.vel.x, rvy + center2.vel.y, rvz + center2.vel.z));

        // Warm gold-white identity
        initialColors.push(1);
        colors[i*3] = 1.0;
        colors[i*3+1] = 0.5 + Math.random() * 0.5;
        colors[i*3+2] = 0.2 + Math.random() * 0.4;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    material = new THREE.PointsMaterial({
        size: 1.0,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        transparent: true,
        opacity: 0.9
    });

    points = new THREE.Points(geometry, material);
    scene.add(points);

    // === CONTROLS ===
    renderer.domElement.addEventListener('mousedown', e => {
        isDragging = true;
        lastMX = e.clientX;
        lastMY = e.clientY;
    });
    window.addEventListener('mouseup', () => isDragging = false);
    window.addEventListener('mousemove', e => {
        if (!isDragging) return;
        const dx = e.clientX - lastMX;
        const dy = e.clientY - lastMY;
        camTheta -= dx * 0.008;
        camPhi += dy * 0.008;
        camPhi = Math.max(0.1, Math.min(Math.PI - 0.1, camPhi));
        lastMX = e.clientX;
        lastMY = e.clientY;
        updateCamera();
    });
    renderer.domElement.addEventListener('wheel', e => {
        camRadius *= 1 + e.deltaY * 0.001;
        camRadius = Math.max(20, Math.min(400, camRadius));
        updateCamera();
    });

    // === ANIMATION ===
    const posArray = geometry.attributes.position.array;
    const colArray = geometry.attributes.color.array;
    let frame = 0;

    function animate() {
        requestAnimationFrame(animate);
        frame++;

        // Slow auto-rotation when not dragging
        if (!isDragging) {
            camTheta += 0.0015;
            updateCamera();
        }

        // --- UPDATE CENTER BODIES (mutual gravity) ---
        const cdx = center2.pos.x - center1.pos.x;
        const cdy = center2.pos.y - center1.pos.y;
        const cdz = center2.pos.z - center1.pos.z;
        const cdistSq = cdx*cdx + cdy*cdy + cdz*cdz + SOFTENING*SOFTENING;
        const cdist = Math.sqrt(cdistSq);
        const cforce = G * center1.mass * center2.mass / cdistSq;
        const cfx = cforce * cdx / cdist;
        const cfy = cforce * cdy / cdist;
        const cfz = cforce * cdz / cdist;

        center1.vel.x += cfx / center1.mass * DT;
        center1.vel.y += cfy / center1.mass * DT;
        center1.vel.z += cfz / center1.mass * DT;
        center2.vel.x -= cfx / center2.mass * DT;
        center2.vel.y -= cfy / center2.mass * DT;
        center2.vel.z -= cfz / center2.mass * DT;

        center1.pos.addScaledVector(center1.vel, DT);
        center2.pos.addScaledVector(center2.vel, DT);

        center1.mesh.position.copy(center1.pos);
        center2.mesh.position.copy(center2.pos);

        // --- UPDATE ALL PARTICLES ---
        for (let i = 0; i < NUM_PARTICLES; i++) {
            const px = posArray[i*3];
            const py = posArray[i*3+1];
            const pz = posArray[i*3+2];

            // Gravity from center 1
            let dx1 = center1.pos.x - px;
            let dy1 = center1.pos.y - py;
            let dz1 = center1.pos.z - pz;
            let d1sq = dx1*dx1 + dy1*dy1 + dz1*dz1 + SOFTENING*SOFTENING;
            let d1 = Math.sqrt(d1sq);
            let f1 = G * center1.mass / d1sq;

            // Gravity from center 2
            let dx2 = center2.pos.x - px;
            let dy2 = center2.pos.y - py;
            let dz2 = center2.pos.z - pz;
            let d2sq = dx2*dx2 + dy2*dy2 + dz2*dz2 + SOFTENING*SOFTENING;
            let d2 = Math.sqrt(d2sq);
            let f2 = G * center2.mass / d2sq;

            // Total acceleration
            const ax = f1 * dx1/d1 + f2 * dx2/d2;
            const ay = f1 * dy1/d1 + f2 * dy2/d2;
            const az = f1 * dz1/d1 + f2 * dz2/d2;

            velocities[i].x += ax * DT;
            velocities[i].y += ay * DT;
            velocities[i].z += az * DT;

            posArray[i*3] += velocities[i].x * DT;
            posArray[i*3+1] += velocities[i].y * DT;
            posArray[i*3+2] += velocities[i].z * DT;

            // Color by velocity (dynamical heating)
            const speed = velocities[i].length();
            const heat = Math.min(1.0, speed / 2.5); // normalize
            const galaxy = initialColors[i];

            if (galaxy === 0) {
                // Galaxy 1 base: blue. Hot = white/pink
                colArray[i*3] = 0.3 + heat * 0.7 + (1-heat) * 0.2;
                colArray[i*3+1] = 0.5 + heat * 0.5 + (1-heat) * 0.2;
                colArray[i*3+2] = 0.8 + heat * 0.2;
            } else {
                // Galaxy 2 base: gold. Hot = white/yellow
                colArray[i*3] = 0.9 + heat * 0.1;
                colArray[i*3+1] = 0.4 + heat * 0.6;
                colArray[i*3+2] = 0.2 + heat * 0.8;
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        // === RENDER WITH TRAIL FADE ===
        // 1. Fade previous frame slightly (creates motion trails)
        renderer.render(fadeScene, fadeCamera);
        // 2. Clear depth so new scene renders properly
        renderer.clearDepth();
        // 3. Render current frame
        renderer.render(scene, camera);
    }

    animate();

    // === RESIZE ===
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
}

// Overlay UI
const overlay = document.createElement('div');
overlay.style.cssText = 'position:absolute;top:20px;left:20px;color:#fff;font-family:Segoe UI,sans-serif;pointer-events:none;text-shadow:0 0 10px rgba(0,0,0,0.9);';
overlay.innerHTML = `
    <h1 style="margin:0;font-size:28px;font-weight:300;letter-spacing:2px;">GALACTIC COLLISION</h1>
    <p style="margin:8px 0 0 0;font-size:14px;opacity:0.8;max-width:400px;line-height:1.5;">
        4,000 stars. Two supermassive cores. One law of gravity.<br>
        Watch tidal tails, bridges, and chaos emerge from perfect simplicity.<br><br>
        <b>Drag</b> to rotate camera • <b>Scroll</b> to zoom
    </p>
`;

document.addEventListener('DOMContentLoaded', () => {
    document.body.appendChild(overlay);
    init();
});

