            let dz1 = center1.pos.z - pz;
            let d1sq = dx1*dx1 + dy1*dy1 + dz1*dz1 + SOFTENING*SOFTENING;
            let d1 = Math.sqrt(d1sq);
            let f1 = G * center1.mass / d1sq;

            // Gravity from center 2
            let dx2 = center2.pos.x - px;
            let dy2 = center2.pos.y - py;
            let dz2 = center2.pos.z - pz;
            let d2sq = dx2*dx2 + dy2*dy2 + dz2*dz2 + SOFTENING*SOFTENING;
            let d2 = Math.sqrt(d2sq);
            let f2 = G * center2.mass / d2sq;

            // Total acceleration
            const ax = f1 * dx1/d1 + f2 * dx2/d2;
            const ay = f1 * dy1/d1 + f2 * dy2/d2;
            const az = f1 * dz1/d1 + f2 * dz2/d2;

            velocities[i].x += ax * DT;
            velocities[i].y += ay * DT;
            velocities[i].z += az * DT;

            posArray[i*3] += velocities[i].x * DT;
            posArray[i*3+1] += velocities[i].y * DT;
            posArray[i*3+2] += velocities[i].z * DT;

            // Color by velocity (dynamical heating)
            const speed = velocities[i].length();
            const heat = Math.min(1.0, speed / 2.5); // normalize
            const galaxy = initialColors[i];

            if (galaxy === 0) {
                // Galaxy 1 base: blue. Hot = white/pink
                colArray[i*3] = 0.3 + heat * 0.7 + (1-heat) * 0.2;
                colArray[i*3+1] = 0.5 + heat * 0.5 + (1-heat) * 0.2;
                colArray[i*3+2] = 0.8 + heat * 0.2;
            } else {
                // Galaxy 2 base: gold. Hot = white/yellow
                colArray[i*3] = 0.9 + heat * 0.1;
                colArray[i*3+1] = 0.4 + heat * 0.6;
                colArray[i*3+2] = 0.2 + heat * 0.8;
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        // === RENDER WITH TRAIL FADE ===
        // 1. Fade previous frame slightly (creates motion trails)
        renderer.render(fadeScene, fadeCamera);
        // 2. Clear depth so new scene renders properly
        renderer.clearDepth();
        // 3. Render current frame
        renderer.render(scene, camera);
    }

    animate();

    // === RESIZE ===
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
}

